package local.lito381.server;
import java.io.*;import java.util.*;import java.util.concurrent.TimeUnit;
/** Static type2 Source targets use the existing canonical normal-NPC constructor and hub-owned lease. */
final class NativeStaticCancellationReplacement {
 static final String FIELD="nativeStaticCancellationRetired";
 static boolean live(GameHub hub,ClassicWorldNpcCatalog.StaticNpc npc,int instance){if(npc==null)return true;synchronized(hub){var a=NativeStaticNpcScene.actor(hub,npc,instance,false);return a==null||!(boolean)CombatAccess.field(a,FIELD);}}
 static boolean live(ClientSession pc,ClassicWorldNpcCatalog.StaticNpc npc){return live((GameHub)CombatAccess.field(pc,"hub"),npc,NativeStaticNpcScene.instance(pc));}
 static boolean nativeStaticRespawnOriginalRoute(ClientSession pc,byte[] packet,BattleSpellCatalog.CancellationSpell spell)throws IOException {var r=Protocol.objectSpellRequest(packet);var npc=ClassicWorldNpcCatalog.npc((int)CombatAccess.field(pc,"classicWorldMapId"),r.targetObjectId());if(npc!=null&&!live(pc,npc))return true;return NativeCancellationNpcStatic.nativeStaticReplacementOriginalRoute(pc,packet,spell);}
 static int routeType(NativeCancellationNpcRules.Rule rule){return rule.type()==2?1:rule.type();}
 static int admissionTarget(NativeCancellationNpcRules.Rule rule){return rule.type()==2?1:rule.targetId();}
 static List<ClassicWorldNpcCatalog.StaticNpc> all(int map,GameHub hub,int instance){return ClassicWorldNpcCatalog.all(map).stream().filter(n->live(hub,n,instance)).toList();}
 static List<ClassicWorldNpcCatalog.StaticNpc> visible(List<ClassicWorldNpcCatalog.StaticNpc> rows,ClientSession pc){return rows.stream().filter(n->live(pc,n)).toList();}
 static boolean prunable(boolean empty,NativeStaticNpcScene.Key key){return empty&&key.instance()>0;}
 static void touch(ClassicWorldNpcCatalog.StaticNpc npc,ClientSession pc){var hub=(GameHub)CombatAccess.field(pc,"hub");synchronized(hub){if(live(pc,npc))NativeStaticNpcMotion.nativeStaticReplacementOriginalTouch(npc,pc);}}
 static void talk(ClientSession pc,ClassicWorldNpcCatalog.StaticNpc npc)throws IOException {var hub=(GameHub)CombatAccess.field(pc,"hub");synchronized(hub){if(live(pc,npc))NativeStaticNpcMotion.nativeStaticReplacementOriginalTalk(pc,npc);}}
 static void dialog(ClientSession pc,long id)throws IOException {if(!NativeStaticNpcRespawn.dialogAllowed(pc,id))return;var hub=(GameHub)CombatAccess.field(pc,"hub");synchronized(hub){var npc=ClassicWorldNpcCatalog.npc((int)CombatAccess.field(pc,"classicWorldMapId"),id);if(live(pc,npc))pc.nativeStaticOriginalDialog(id);}}
 static boolean poseLive(ClientSession pc,NativeStaticNpcMotion.Pose pose){return !(pose.actor() instanceof NativeStaticNpcMotion.Motion m)||!(boolean)CombatAccess.field(m,FIELD);}
 static boolean frame(ClientSession pc,byte[] packet,String note)throws IOException {
  if(packet.length<5)return false;int op=packet[0]&255;int offset=op==Protocol.S_PUT_OBJECT?5:1;if(packet.length<offset+4||!NativeStaticNpcMotion.PACKETS.contains(op))return false;var npc=ClassicWorldNpcCatalog.npc((int)CombatAccess.field(pc,"classicWorldMapId"),NativeStaticNpcMotion.id(packet,offset));if(npc==null||live(pc,npc))return false;
  if(op==Protocol.S_REMOVE_OBJECT){var state=NativeStaticNpcMotion.state((GameHub)CombatAccess.field(pc,"hub"),false);synchronized(pc){if(state!=null)synchronized(state.viewers){var view=state.viewers.get(pc);if(view!=null)view.epoch.known.remove(npc.objectId());}pc.nativeStaticOriginalFrame(packet,note);}}return true;
 }
 static void retired(GameHub hub,ClassicWorldNpcCatalog.StaticNpc npc,int instance){if(!Thread.holdsLock(hub))throw new IllegalStateException("static replacement requires owned scene");var actor=NativeStaticNpcScene.actor(hub,npc,instance,true);CombatAccess.set(actor,FIELD,true);var motion=NativeStaticNpcMotion.state(hub,false);if(motion!=null){var m=motion.actors.remove(new NativeStaticNpcScene.Key(npc.mapId(),instance,npc.objectId()));if(m!=null)CombatAccess.set(m,FIELD,true);NativeStaticNpcMotion.publish(hub,motion);}}
 record Retired(GameHub hub,ClassicWorldNpcCatalog.StaticNpc npc,int instance,NativeStaticNpcScene.Actor actor,List<NativeCancellationNpcRuntime.Viewer> viewers) {
  void publish(){for(var v:viewers){Runnable[] out={null};NativeSourcePlayerActionLock.run(v.pc(),()->{if(v.binding().matches(v.pc()))out[0]=NativeRolePublication.completion(v.pc(),()->{boolean ok;synchronized(hub){ok=v.binding().matches(v.pc())&&NativeStaticNpcScene.inScene(v.pc(),hub,npc.mapId(),instance)&&NativeStaticNpcScene.actor(hub,npc,instance,false)==actor&&!live(hub,npc,instance);}if(ok)try{NativeStaticNpcRespawn.sendRetired(v.pc(),Protocol.removeObject(npc.objectId()),"S_REMOVE_OBJECT static-type2-Cancellation",this);}catch(IOException e){throw new UncheckedIOException(e);}});});if(out[0]!=null)out[0].run();}}
 }
 static void publish(NativeCancellationNpcRuntime.Notice notice){for(var v:notice.viewers()){Runnable[] out={null};NativeSourcePlayerActionLock.run(v.pc(),()->{if(v.binding().matches(v.pc()))out[0]=NativeRolePublication.completion(v.pc(),()->new NativeCancellationNpcRuntime.Notice(notice.hub(),notice.population(),notice.map(),notice.instance(),notice.snapshot(),notice.actor(),notice.removed(),List.of(v)).publish());});if(out[0]!=null)out[0].run();}}
 static boolean apply(NativeCancellationNpcTransform.Target target,NativeCancellationNpcRules.Rule rule,NativeCancellationNpcTransform.Spawn unused){
  if(rule.type()!=2)return NativeCancellationNpcTransform.apply(target,rule,unused);var t=(NativeCancellationNpcStatic.Target)target;var hub=t.hub;var pc=t.pc;if(!Thread.holdsLock(hub)||!pc.nativePlayerActionLock().isHeldByCurrentThread()||!NativeLightAction.retainedMaterial(pc))throw new IllegalStateException("static type2 requires committed canonical cast");
  if(!live(hub,t.npc,t.instance)||(boolean)CombatAccess.field(hub,"nativeStaticMotionClosed"))return false;var template=NativeCancellationNpcRuntime.template(rule.targetId());var pop=NativeCancellationNpcMaterialAction.population(hub,t.getMapId(),t.instance);if(template==null||pop==null)return false;
  var state=NativeCancellationNpcRuntime.state(hub);if(!NativeCancellationNpcRuntime.start(state))return false;
  synchronized(pop){try(var allocation=new Allocation(pop,t.getMapId(),t.getX(),t.getY())){
   ClassicWorldMonsterPopulation.Snapshot created;try{created=pop.nativeStaticCancellationSpawn(t.getMapId(),t.npc.spawnId(),t.getX(),t.getY(),t.getHeading(),template);}catch(RuntimeException failure){System.err.println("[LiTo] static type2 factory failed: "+failure.getClass().getSimpleName());NativeCancellationNpcRuntime.stopEmpty(state);return false;}if(created==null){NativeCancellationNpcRuntime.stopEmpty(state);return false;}
   var key=new NativeStaticNpcScene.Key(t.getMapId(),t.instance,t.npc.objectId());var previous=NativeStaticNpcScene.actor(hub,t.npc,t.instance,false);var motion=NativeStaticNpcMotion.state(hub,false);var previousMotion=motion==null?null:motion.actors.get(key);boolean committed=false;
   try {var lease=new NativeCancellationNpcRuntime.Lease(pop,t.getMapId(),t.instance,created.objectId(),rule.durationSeconds()==0?0:System.nanoTime()+TimeUnit.SECONDS.toNanos(rule.durationSeconds()),false);state.leases.add(lease);retired(hub,t.npc,t.instance);NativeStaticNpcRespawn.accepted(target);committed=allocation.committed=true;var spawned=NativeCancellationNpcRuntime.notice(hub,pop,t.getMapId(),t.instance,created,NativeCancellationNpcMaterialAction.actor(pop,created.objectId()),false);var removed=new Retired(hub,t.npc,t.instance,NativeStaticNpcScene.actor(hub,t.npc,t.instance,false),spawned.viewers());NativeLightAction.finishScoped((published,failure)->{publish(spawned);removed.publish();});return true;
   } catch(RuntimeException failure){if(committed)throw failure;System.err.println("[LiTo] static type2 registration failed: "+failure.getClass().getSimpleName());return false;}finally {if(!committed){state.leases.removeIf(l->!l.respawn&&l.population==pop&&l.id==created.objectId());var scene=NativeStaticNpcScene.state(hub,false);if(scene!=null){if(previous==null)scene.actors.remove(key);else CombatAccess.set(previous,FIELD,false);}if(previousMotion!=null){CombatAccess.set(previousMotion,FIELD,false);motion.actors.put(key,previousMotion);NativeStaticNpcMotion.publish(hub,motion);}NativeCancellationNpcRuntime.stopEmpty(state);}}
  }}

 }
 static final class Allocation implements AutoCloseable {
  final ClassicWorldMonsterPopulation pop;final long id;final Object key,previousActor;final Integer occupied;boolean committed;
  Allocation(ClassicWorldMonsterPopulation pop,int map,int x,int y){this.pop=pop;id=(long)CombatAccess.field(pop,"nextQuestDynamicObjectId");previousActor=((Map<?,?>)CombatAccess.field(pop,"actors")).get(id);try{var ctor=Class.forName("local.lito381.server.ClassicWorldMonsterPopulation$Cell",false,pop.getClass().getClassLoader()).getDeclaredConstructor(int.class,int.class,int.class);ctor.setAccessible(true);key=ctor.newInstance(map,x,y);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}occupied=(Integer)((Map<?,?>)CombatAccess.field(pop,"occupied")).get(key);}
  @SuppressWarnings("unchecked")public void close(){if(committed)return;var actors=(Map<Long,Object>)CombatAccess.field(pop,"actors");if(previousActor==null)actors.remove(id);else if(actors.get(id)!=previousActor)actors.put(id,previousActor);var cells=(Map<Object,Integer>)CombatAccess.field(pop,"occupied");if(occupied==null)cells.remove(key);else cells.put(key,occupied);CombatAccess.set(pop,"nextQuestDynamicObjectId",id);}
 }
 static boolean route(ClientSession pc,byte[] packet,BattleSpellCatalog.CancellationSpell spell)throws IOException{return NativeStaticNpcRespawn.route(pc,packet,spell);}
 private NativeStaticCancellationReplacement(){}
}
